-- Generated by monitor-oc: https://github.com/Ravenor907/Fedora-Monitor-Overclocker
--
-- Extends Gamescope's refresh-rate range (SteamOS Game Mode) for one built-in
-- panel. Remove it with `monitor-oc panel remove`, or delete this file and
-- restart Game Mode.
--
-- Safety: a new rate starts as a one-session trial. If Gamescope starts again
-- before the trial is confirmed (for example after a forced reboot from a black
-- screen), the trial is dropped and the panel goes back to its stock range.

local MONITOR_OC_KEY = "monitor_oc_panel"
local panel = {
    vendor = @@VENDOR@@,
    product = @@PRODUCT@@,
    model = @@MODEL@@,
    data_string = @@DATA_STRING@@,
}
local state_path = @@STATE_PATH@@
local report_path = @@REPORT_PATH@@
-- Refresh rates the panel's EDID lists at its native resolution.
local edid_rates = { @@EDID_RATES@@ }
-- Smallest vertical front porch the "porch" method will shrink to.
local MIN_VFP = 3

local function log(priority, text)
    if gamescope and gamescope.log and gamescope.log_priority then
        gamescope.log(gamescope.log_priority[priority], "[monitor-oc] " .. text)
    end
end

local STATE_KEYS = { "max", "method", "trial", "trial_state" }

local function read_kv(path)
    local out = {}
    local f = io.open(path, "r")
    if not f then
        return out
    end
    for line in f:lines() do
        local k, v = line:match("^%s*([%w_]+)%s*=%s*(.-)%s*$")
        if k then
            out[k] = v
        end
    end
    f:close()
    return out
end

local function write_kv(path, tbl, keys)
    local f = io.open(path, "w")
    if not f then
        return false
    end
    for _, k in ipairs(keys) do
        if tbl[k] ~= nil then
            f:write(k .. "=" .. tostring(tbl[k]) .. "\n")
        end
    end
    f:close()
    return true
end

local report = {}
local REPORT_KEYS = {
    "loaded_at", "base", "base_name", "stock_min", "stock_max", "limit",
    "method", "trial", "extended", "last_refresh", "last_mode", "last_clock_khz",
}
local function save_report()
    write_kv(report_path, report, REPORT_KEYS)
end

-- Work out how far this Gamescope session may go.
local state = read_kv(state_path)
local limit = tonumber(state.max) or 0
local trial = tonumber(state.trial)
local method = (state.method == "porch") and "porch" or "clock"

if trial then
    if state.trial_state == "armed" then
        -- First start since the trial was requested: enable it for this session
        -- only, and record that it has been used. Only enable it if the record
        -- was written, otherwise the next start could not drop it.
        state.trial_state = "running"
        if write_kv(state_path, state, STATE_KEYS) then
            limit = math.max(limit, trial)
            report.trial = "running"
        else
            log("error", "cannot write " .. state_path .. "; not enabling the trial")
            report.trial = "not-writable"
        end
    elseif state.trial_state == "running" then
        -- Gamescope started again without the trial being confirmed.
        state.trial_state = "expired"
        write_kv(state_path, state, STATE_KEYS)
        report.trial = "expired"
        log("warning", "trial at " .. trial .. " Hz was not confirmed; using the stock range")
    else
        report.trial = state.trial_state or "none"
    end
end

-- Find the profile Gamescope would use for this panel without us.
local base, base_key, best = nil, nil, -1
for key, display in pairs(gamescope.config.known_displays) do
    if key ~= MONITOR_OC_KEY and type(display) == "table" and type(display.matches) == "function" then
        local ok, priority = pcall(display.matches, panel)
        if ok and type(priority) == "number" and priority > best then
            base, base_key, best = display, key, priority
        end
    end
end
if best < 0 then
    base, base_key = nil, nil
end

local stock_rates = {}
local source = edid_rates
if base and type(base.dynamic_refresh_rates) == "table" then
    source = base.dynamic_refresh_rates
end
for _, r in ipairs(source) do
    table.insert(stock_rates, r)
end
table.sort(stock_rates)
local stock_min = stock_rates[1] or 0
local stock_max = stock_rates[#stock_rates] or 0

report.loaded_at = os.time()
report.base = base_key or "none"
report.base_name = base and base.pretty_name or "none"
report.stock_min = stock_min
report.stock_max = stock_max
report.limit = limit
report.method = method

if stock_max == 0 or limit <= stock_max then
    report.extended = "no"
    save_report()
    log("info", "nothing to extend (limit " .. limit .. " Hz, stock max " .. stock_max .. " Hz)")
    return
end

local function copy(t)
    local out = {}
    for k, v in pairs(t) do
        out[k] = v
    end
    return out
end

local function set_vfp(mode, vfp)
    local vsync = mode.vsync_end - mode.vsync_start
    local vbp = mode.vtotal - mode.vsync_end
    mode.vsync_start = mode.vdisplay + vfp
    mode.vsync_end = mode.vsync_start + vsync
    mode.vtotal = mode.vsync_end + vbp
end

local function vfp_for(mode, refresh)
    local vsync = mode.vsync_end - mode.vsync_start
    local vbp = mode.vtotal - mode.vsync_end
    local vtotal = math.floor(mode.clock * 1000 / (mode.htotal * refresh))
    return vtotal - mode.vdisplay - vsync - vbp
end

local function finish(mode, refresh)
    mode.vrefresh = math.floor((1000 * mode.clock) / (mode.htotal * mode.vtotal))
    report.last_refresh = refresh
    report.last_mode = mode.hdisplay .. "x" .. mode.vdisplay .. "@" .. refresh
    report.last_clock_khz = mode.clock
    save_report()
    return mode
end

local rates = {}
for _, r in ipairs(stock_rates) do
    table.insert(rates, r)
end
for r = stock_max + 1, limit do
    table.insert(rates, r)
end

local ours = base and copy(base) or {}
ours.pretty_name = (base and base.pretty_name or "Built-in display") .. " (monitor-oc, up to " .. limit .. " Hz)"
ours.dynamic_refresh_rates = rates
ours.dynamic_modegen = function(base_mode, refresh)
    if refresh <= stock_max then
        if base and type(base.dynamic_modegen) == "function" then
            return base.dynamic_modegen(copy(base_mode), refresh)
        end
        -- No stock profile: keep the pixel clock and stretch the front porch.
        local mode = copy(base_mode)
        local vfp = vfp_for(mode, refresh)
        if vfp >= MIN_VFP then
            set_vfp(mode, vfp)
        else
            mode.clock = math.floor((mode.htotal * mode.vtotal * refresh + 999) / 1000)
        end
        return finish(mode, refresh)
    end

    if refresh > limit then
        log("warning", refresh .. " Hz is above the enabled limit of " .. limit .. " Hz; using the native mode")
        return base_mode
    end

    -- Start from the panel's timing at its stock maximum (fixed pixel clock,
    -- front porch adjusted), so both methods scale from the real native mode.
    local mode = copy(base_mode)
    local native_vfp = vfp_for(mode, stock_max)
    if native_vfp >= MIN_VFP then
        set_vfp(mode, native_vfp)
    end

    if method == "porch" then
        -- Shrink the blanking first and keep the pixel clock; raise the clock
        -- only for whatever the blanking cannot cover.
        local vfp = vfp_for(mode, refresh)
        if vfp >= MIN_VFP then
            set_vfp(mode, vfp)
            return finish(mode, refresh)
        end
        set_vfp(mode, MIN_VFP)
    end

    -- Keep the blanking and raise the pixel clock.
    mode.clock = math.floor((mode.htotal * mode.vtotal * refresh + 999) / 1000)
    return finish(mode, refresh)
end
local function trim(s)
    return (tostring(s or "")):match("^%s*(.-)%s*$")
end
ours.matches = function(display)
    if trim(display.vendor) ~= panel.vendor or tonumber(display.product) ~= panel.product then
        return -1
    end
    if (panel.model ~= "" and trim(display.model) == panel.model)
        or (panel.data_string ~= "" and trim(display.data_string) == panel.data_string)
        or (panel.model == "" and panel.data_string == "") then
        return 10000
    end
    return -1
end

gamescope.config.known_displays[MONITOR_OC_KEY] = ours
report.extended = "yes"
save_report()
log("info", "extended " .. (base and base.pretty_name or "built-in display") .. " to " .. limit .. " Hz (" .. method .. ")")
